import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.DgVVaeR-.js";const o="/Palleria/assets/bookmark.B1b-VaPO.png",i="/Palleria/assets/profile_page1.BDxLT8uu.png",p="/Palleria/assets/profile_page2.Bw27zUah.png",m=JSON.parse('{"title":"ブックマークとプロフィール","description":"","frontmatter":{"title":"ブックマークとプロフィール"},"headers":[],"relativePath":"user/bookmarks.md","filePath":"user/bookmarks.md","lastUpdated":1791087203000}'),l={name:"user/bookmarks.md"};function n(c,a,_,d,f,g){return t(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="ブックマークとプロフィール" tabindex="-1">ブックマークとプロフィール <a class="header-anchor" href="#ブックマークとプロフィール" aria-label="Permalink to &quot;ブックマークとプロフィール&quot;">​</a></h1><h2 id="ハートでブックマークする" tabindex="-1">ハートでブックマークする <a class="header-anchor" href="#ハートでブックマークする" aria-label="Permalink to &quot;ハートでブックマークする&quot;">​</a></h2><p>作品のハートはブックマークの追加・解除です。通常のタップでは設定した既定の公開範囲を使います。未登録のイラストでハートを長押しすると、非公開ブックマークとして追加します。タグ選択ダイアログを開く操作ではありません。</p><p>登録済みの作品ではハート操作が解除になるため、公開範囲を変更するつもりで押さないようにしてください。通信後に結果が画面へ反映されます。</p><figure class="app-screenshot"><p><img src="'+o+'" alt="タイムライン・ブックマーク・Watchlist・フォロー中のタブ" loading="lazy"></p><figcaption>ブックマーク画面。塗りつぶされたハートは登録済みの作品です。</figcaption></figure><h2 id="フォローとプロフィール" tabindex="-1">フォローとプロフィール <a class="header-anchor" href="#フォローとプロフィール" aria-label="Permalink to &quot;フォローとプロフィール&quot;">​</a></h2><p>作品の作者名・アイコンからプロフィールを開けます。フォローすると、フォロー中ユーザーの新着を一覧から確認できます。公開・非公開の扱いはフォロー操作の設定に従います。</p><p>プロフィールの「作品」「ブックマーク」「情報」を切り替えると、投稿作品、閲覧できるブックマーク、ユーザー情報を確認できます。「情報」タブには作品用の並べ替え・絞り込みボタンを表示しません。</p><div class="screenshot-grid"><figure class="app-screenshot"><p><img src="'+i+'" alt="作者のヘッダー、フォローボタン、作品タブ" loading="lazy"></p><figcaption>プロフィール上部。作品・ブックマーク・情報を切り替えられます。</figcaption></figure><figure class="app-screenshot"><p><img src="'+p+'" alt="スクロール後にコンパクトになったプロフィールのヘッダー" loading="lazy"></p><figcaption>下へスクロールするとヘッダーが縮まり、作品一覧を広く表示します。</figcaption></figure></div>',9)])])}const u=e(l,[["render",n]]);export{m as __pageData,u as default};
